SET request.jwt.claim.sub='';
CALL pg_temp.version_write('atomic score update',$cmd$SELECT public.update_score_points_atomic(league_id,season_id,1,jsonb_build_array(jsonb_build_object('id',matchup_id,'home_points',9,'away_points',4))) FROM version_fixture$cmd$);
CALL pg_temp.version_write('live box worker',$cmd$SELECT public.save_live_game_stats_atomic(game_id,'0029562001',jsonb_build_array(jsonb_build_object('game_id',game_id,'season_year',9562,'game_date',current_date,'week_number',1,'did_not_play',false,'player_id',players[1],'points',7,'is_home',true)),20) FROM version_fixture$cmd$);
CALL pg_temp.version_write('final box worker',$cmd$SELECT public.save_final_game_snapshot_atomic(game_id,'0029562001',jsonb_build_array(jsonb_build_object('game_id',game_id,'season_year',9562,'game_date',current_date,'week_number',1,'did_not_play',false,'player_id',players[1],'points',9,'is_home',true)),clock_timestamp(),9,4,'Final') FROM version_fixture$cmd$);
CALL pg_temp.version_write('score finalization',$cmd$SELECT public.finalize_score_week_atomic(league_id,season_id,1,jsonb_build_array(jsonb_build_object('id',matchup_id,'home_points',9,'away_points',4,'winner_member_id',member_ids[1],'home_max_possible_points',9,'away_max_possible_points',4,'input_token',public.capture_score_inputs(season_id,1))),'[]') FROM version_fixture$cmd$);
CALL pg_temp.version_write('stale final snapshot',$cmd$SELECT public.save_final_game_snapshot_atomic(game_id,'0029562001',jsonb_build_array(jsonb_build_object('game_id',game_id,'season_year',9562,'game_date',current_date,'week_number',1,'did_not_play',false,'player_id',players[1],'points',1,'is_home',true)),now()-interval '1 day',1,0,'Final') FROM version_fixture$cmd$,0);
SELECT set_config('request.jwt.claim.sub',(SELECT user_ids[1]::text FROM version_fixture),false);
